import React, { useState } from "react";
import { motion } from "framer-motion";
import { User, Building, Mail, Phone, Lock } from "lucide-react";
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";

const colors = {
  blueMain: "#003865",
  orange: "#ef5b0c",
  gray: "#d9d9d9",
};

const InputField = ({
  icon: Icon,
  type = "text",
  placeholder,
  value,
  onChange,
  error,
}) => (
  <div className="relative mb-4">
    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
      <Icon className="h-5 w-5 text-gray-400" />
    </div>
    <input
      type={type}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      className={`w-full pl-10 pr-4 py-3 bg-white border ${
        error ? "border-red-500" : "border-gray-300"
      } rounded-xl text-black placeholder-gray-500 focus:outline-none focus:border-[${
        colors.blueMain
      }] focus:ring-2 focus:ring-[${
        colors.blueMain
      }]/20 transition-all duration-300`}
      style={{
        backgroundColor: colors.gray,
      }}
    />
    {error && (
      <motion.p
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-red-500 text-sm mt-1 ml-1"
      >
        {error}
      </motion.p>
    )}
  </div>
);

const Button = ({ children, disabled = false, onClick }) => (
  <motion.button
    whileHover={!disabled ? { scale: 1.02 } : {}}
    whileTap={!disabled ? { scale: 0.98 } : {}}
    disabled={disabled}
    onClick={onClick}
    className="w-full text-white font-semibold py-3 px-6 rounded-xl shadow-lg transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
    style={{
      backgroundColor: colors.orange,
    }}
  >
    {children}
  </motion.button>
);

export default function Inscription() {
  const [formData, setFormData] = useState({
    entreprise: "",
    nom: "",
    prenom: "",
    email: "",
    telephone: "",
  });
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (field) => (e) => {
    setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.entreprise.trim())
      newErrors.entreprise = "Nom de l'entreprise requis";
    if (!formData.nom.trim()) newErrors.nom = "Nom requis";
    if (!formData.prenom.trim()) newErrors.prenom = "Prénom requis";
    if (!formData.email.trim()) {
      newErrors.email = "Email requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Format d'email invalide";
    }
    if (!formData.telephone.trim()) {
      newErrors.telephone = "Téléphone requis";
    }
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      alert("Inscription réussie !");
    }, 2000);
  };

  return (
    <>
      <Navbar />
      <div className="min-h-screen bg-white flex items-center justify-center px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="relative max-w-md w-full space-y-8 my-20"
        >
          <div className="bg-white rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-200">
            <div className="text-center mb-8">
              <motion.h2
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.2 }}
                className="text-2xl sm:text-3xl font-bold"
                style={{ color: colors.blueMain }}
              >
                Créer un compte entreprise
              </motion.h2>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.4 }}
                className="mt-2 text-sm text-gray-600"
              >
                Rejoignez Veille Marchés dès aujourd'hui
              </motion.p>
            </div>

            <div className="space-y-4">
              <InputField
                icon={Building}
                placeholder="Nom de l'entreprise"
                value={formData.entreprise}
                onChange={handleChange("entreprise")}
                error={errors.entreprise}
              />

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <InputField
                  icon={User}
                  placeholder="Nom du représentant"
                  value={formData.nom}
                  onChange={handleChange("nom")}
                  error={errors.nom}
                />
                <InputField
                  icon={User}
                  placeholder="Prénom du représentant"
                  value={formData.prenom}
                  onChange={handleChange("prenom")}
                  error={errors.prenom}
                />
              </div>

              <InputField
                icon={Mail}
                type="email"
                placeholder="Adresse email"
                value={formData.email}
                onChange={handleChange("email")}
                error={errors.email}
              />

              <InputField
                icon={Phone}
                type="tel"
                placeholder="Téléphone"
                value={formData.telephone}
                onChange={handleChange("telephone")}
                error={errors.telephone}
              />

              <div className="pt-4">
                <Button disabled={isLoading} onClick={handleSubmit}>
                  {isLoading ? "Création en cours..." : "Créer mon compte"}
                </Button>
              </div>
            </div>

            <div className="mt-6 text-center">
              <p className="text-sm text-gray-600">
                Déjà un compte ?{" "}
                <a
                  href="/connexion"
                  style={{ color: colors.orange }}
                  className="font-medium hover:underline"
                >
                  Se connecter
                </a>
              </p>
            </div>

            <div className="mt-4 text-center">
              <p className="text-xs text-gray-500">
                En vous inscrivant, vous acceptez nos{" "}
                <a
                  href="#"
                  style={{ color: colors.orange }}
                  className="hover:underline"
                >
                  conditions d'utilisation
                </a>{" "}
                et notre{" "}
                <a
                  href="#"
                  style={{ color: colors.orange }}
                  className="hover:underline"
                >
                  politique de confidentialité
                </a>
              </p>
            </div>
          </div>
        </motion.div>
      </div>
      <Footer />
    </>
  );
}
